#endif

#if HWY_ARCH_ARM && HWY_HAVE_RUNTIME_DISPATCH
#if !HWY_OS_APPLE
static unsigned long cvectorization_ops_getauxval(unsigned long type) {
#if HWY_OS_FREEBSD || HWY_OS_OPENBSD
  unsigned long hwcap = 0;
  switch (type) {
  case AT_HWCAP:
  case AT_HWCAP2:
    if (elf_aux_info((int)type, &hwcap, sizeof(hwcap)) != 0) hwcap = 0;
    return hwcap;
  default:
    return 0;
  }
#else
  return getauxval(type);
#endif
}
#endif
#if HWY_ARCH_ARM_A64 && !HWY_OS_APPLE && (HWY_COMPILER_GCC || HWY_COMPILER_CLANG) && ((HWY_TARGETS & HWY_ALL_SVE) != 0)
static __attribute__((target("+sve"))) int64_t cvectorization_ops_arm_detect_additional_sve_targets(int64_t detected_targets) {
  uint64_t sve_vec_len;
  __asm__("cntb %0" : "=r"(sve_vec_len)::);
  return ((sve_vec_len == 32) ? HWY_SVE_256 : (((detected_targets & HWY_SVE2) != 0 && sve_vec_len == 16) ? HWY_SVE2_128 : 0));
}
#endif
static int64_t cvectorization_ops_arm_detect_targets_impl(void) {
  int64_t bits = 0;
#if defined(AT_HWCAP) && !HWY_OS_APPLE
  const unsigned long hw = cvectorization_ops_getauxval(AT_HWCAP);
#else
  const unsigned long hw = 0UL;
#endif
  (void)hw;
#if HWY_ARCH_ARM_A64
  bits |= HWY_NEON_WITHOUT_AES;
#if HWY_OS_APPLE
  if (cvectorization_ops_has_cpu_feature("hw.optional.arm.FEAT_AES")) {
    bits |= HWY_NEON;
    if ((cvectorization_ops_has_cpu_feature("hw.optional.AdvSIMD_HPFPCvt") || cvectorization_ops_has_cpu_feature("hw.optional.arm.AdvSIMD_HPFPCvt")) && cvectorization_ops_has_cpu_feature("hw.optional.arm.FEAT_DotProd") && cvectorization_ops_has_cpu_feature("hw.optional.arm.FEAT_BF16") && cvectorization_ops_has_cpu_feature("hw.optional.arm.FEAT_I8MM")) {
      bits |= HWY_NEON_BF16;
    }
  }
#else
#if defined(HWCAP_AES)
  if (hw & HWCAP_AES) {
    bits |= HWY_NEON;
#if defined(AT_HWCAP2) && defined(HWCAP_ASIMDHP) && defined(HWCAP_ASIMDDP) && defined(HWCAP2_BF16)
    const unsigned long hw2 = cvectorization_ops_getauxval(AT_HWCAP2);
    const unsigned long group_f16_dot = HWCAP_ASIMDHP | HWCAP_ASIMDDP;
    const unsigned long group_bf16 = HWCAP2_BF16;
    if ((hw & group_f16_dot) == group_f16_dot && (hw2 & group_bf16) == group_bf16) {
      bits |= HWY_NEON_BF16;
    }
#endif
  }
#endif
#if defined(HWCAP_SVE)
  if (hw & HWCAP_SVE) {
    bits |= HWY_SVE;
  }
#endif
#ifndef HWCAP2_SVE2
#define HWCAP2_SVE2 (1 << 1)
#endif
#ifndef HWCAP2_SVEAES
#define HWCAP2_SVEAES (1 << 2)
#endif
#ifndef HWCAP2_SVEI8MM
#define HWCAP2_SVEI8MM (1 << 9)
#endif
#ifndef HWCAP2_SVEBF16
#define HWCAP2_SVEBF16 (1 << 12)
#endif
  const unsigned long group_sve2 = HWCAP2_SVE2 | HWCAP2_SVEAES;
#if defined(AT_HWCAP2)
  const unsigned long hw2 = cvectorization_ops_getauxval(AT_HWCAP2);
#else
  const unsigned long hw2 = 0UL;
#endif
  if ((hw2 & group_sve2) == group_sve2) {
    bits |= HWY_SVE2;
  }
#if (HWY_COMPILER_GCC || HWY_COMPILER_CLANG) && ((HWY_TARGETS & HWY_ALL_SVE) != 0)
  if ((bits & HWY_ALL_SVE) != 0) {
    bits |= cvectorization_ops_arm_detect_additional_sve_targets(bits);
    const unsigned long group_sve2_128 = HWCAP2_SVEI8MM | HWCAP2_SVEBF16;
    if ((hw2 & group_sve2_128) != group_sve2_128) {
      bits &= ~HWY_SVE2_128;
    }
  }
#endif
#endif
#else
#if defined(HWCAP_NEON) && defined(HWCAP_VFPv4)
  if ((hw & HWCAP_NEON) && (hw & HWCAP_VFPv4)) {
    bits |= HWY_NEON_WITHOUT_AES;
  }
#endif
#endif
  return bits;
}
#endif

int64_t cvectorization_ops_supported_targets(void) {
  int64_t bits = HWY_SCALAR | HWY_EMU128;
#if HWY_ARCH_X86 && HWY_HAVE_RUNTIME_DISPATCH
  bits |= cvectorization_ops_x86_detect_targets_impl();
#elif HWY_ARCH_ARM && HWY_HAVE_RUNTIME_DISPATCH
  bits |= cvectorization_ops_arm_detect_targets_impl();
#else
  bits |= HWY_ENABLED_BASELINE;
#endif
  return bits;
}

bool cvectorization_ops_vector_length_matches(void) {
#if HWY_STATIC_TARGET & (HWY_SVE | HWY_SVE2)
  uint64_t sve_vec_len;
  __asm__("cntb %0" : "=r"(sve_vec_len)::);
  return sve_vec_len == CVECTORIZATION_OPS_VECTOR_BYTES;
#else
  return true;
#endif
}
